package dev.zomboid.hordes;
import java.util.*;import java.lang.reflect.*;
public final class ApocalypsePanel {
 static String[][]baseHints;
 static final int FIRST=10;static final Map<Object,Integer>selected=new WeakHashMap<>();
 static final String[] names={"Dificultad","Loot y NPC","Poblacion","Limpieza","Cofres","Drops","Cadaveres","Spawn e IA","Velocidad y dano","Cooldowns melee","Mundo y medicina","Mutantes","Profesiones 1/4","Profesiones 2/4","Profesiones 3/4","Profesiones 4/4"};
 public static String[][] rows(String[][] old,String kind){
  List<String[]>out=new ArrayList<>(Arrays.asList(old));
  String[]labels={"Cadaveres por profesion","Zombis con profesion (%)","Reconocer equipo y nombres","Conservar ropa vestida","Curar al subir de nivel","Inyeccion en loot (%)","Loot de profesion (x)"};
  String[]hints={"Activa el loot profesional en cuerpos nuevos; no cambia cuerpos ya abiertos ni carga de NPC.","0-100% de zombis nuevos reciben una profesion del pool. Las profesiones reconocidas por aspecto se respetan.","Lee equipo, profesion real y reglas del catalogo. Las texturas aleatorias de TZP son del cliente: se necesita un mapa explicito, no reconocimiento magico del servidor.","Copia las prendas realmente equipadas. Los perfiles vestidos usan ropa registrada; desnudo no genera ropa. Ropa conservada no depende de la escasez de suministros.","Opcional y apagado de inicio. Cualquier nivel nuevo de habilidad restaura ocho partes, lesiones, salud y elimina todos los efectos, incluida infeccion zombi.","Probabilidad por generacion de loot NUEVO; multiplicada por su escasez. 0 nunca. No reemplaza el antibiotico ni cura otras lesiones.","0-10x; se combina con Cantidad de Cadaveres. 0 quita suministros profesionales. No reduce equipo real de NPC/jugadores."};
  out.add(kind.equals("KEYS")?ApocalypseSettings.GLOBAL:kind.equals("LABELS")?labels:hints);
  String[]m=new String[7];for(int i=0;i<7;i++)m[i]=kind.equals("KEYS")?"mutante_pool_"+ApocalypseSettings.MUTANTS[i]:kind.equals("LABELS")?new String[]{"Rastrero","Ampollado","Cabeza partida","Mutante podrido","Escupidor","Zombi bruto","Mutante bruto"}[i]+" (peso)":"Peso relativo dentro de los mutantes de ZH. 0 excluye. Todos en 0 desactiva el selector. No controla spawns de otros mods ni elimina existentes.";out.add(m);
  for(int start=0;start<ProfessionCatalog.IDS.length;start+=10){int n=Math.min(10,ProfessionCatalog.IDS.length-start);String[]r=new String[n];for(int j=0;j<n;j++){int i=start+j;r[j]=kind.equals("KEYS")?"cadaver_pool_"+ProfessionCatalog.IDS[i]:kind.equals("LABELS")?ProfessionCatalog.LABELS[i]+" (peso)":"Peso relativo, no porcentaje absoluto. 0 excluye del sorteo; un equipo o profesion real reconocida tiene prioridad. Loot: "+ProfessionCatalog.LOOT[i]+". Editable en catalogo.";}out.add(r);}
  String[][]result=out.toArray(String[][]::new);if(kind.equals("HINTS")){baseHints=Arrays.stream(result).map(String[]::clone).toArray(String[][]::new);}return result;
 }
 static Object c(Object o,String name,Object...a){return ZoneReflection.call(o,name,a);}static int number(Object o,String name){return ((Number)ZoneReflection.get(o,name)).intValue();}
 static void set(Object o,String name,Object v){try{for(Class<?>t=o.getClass();t!=null;t=t.getSuperclass())try{Field f=t.getDeclaredField(name);f.setAccessible(true);f.set(o,v);return;}catch(NoSuchFieldException e){}throw new NoSuchFieldException(name);}catch(Exception e){throw new IllegalStateException(e);}}
 static void button(Object screen,String text,int x,int y,int w,Runnable action){Class<?>on=ZoneReflection.type("net.minecraft.client.gui.components.Button$OnPress");Object cb=Proxy.newProxyInstance(on.getClassLoader(),new Class[]{on},(p,m,a)->{if(m.getName().equals("onPress"))action.run();return null;});Object component=c(ZoneReflection.type("net.minecraft.network.chat.Component"),"literal",text);Object builder=c(ZoneReflection.type("net.minecraft.client.gui.components.Button"),"builder",component,cb);c(builder,"bounds",x,y,w,20);c(screen,"addRenderableWidget",c(builder,"build"));}
 @SuppressWarnings("unchecked")static void refreshHints(Object screen){if(baseHints==null)return;try{String[][]hints=(String[][])ZoneReflection.get(screen.getClass(),"HINTS");Map<String,Double>d=(Map<String,Double>)ZoneReflection.get(screen,"draft");for(int page=11;page<16;page++){String[]ids=page==11?ApocalypseSettings.MUTANTS:ProfessionCatalog.IDS;String prefix=page==11?"mutante_pool_":"cadaver_pool_";double[]w=ApocalypseSettings.weights(d,prefix,ids);double sum=Arrays.stream(w).sum();int from=page==11?0:(page-12)*10;for(int j=0;j<hints[page].length;j++){int i=from+j;hints[page][j]=String.format(Locale.ROOT,"Probabilidad del pool: %.2f%%. Peso %.2f de %.2f. ",sum>0?w[i]*100/sum:0,w[i],sum)+baseHints[page][j];}}}catch(RuntimeException e){/* API doubles and alternative screens have no native HINTS field. */}}
 public static String[] tabs(String[]ignored,Object screen){refreshHints(screen);int page=number(screen,"page"),left=number(screen,"left"),width=Math.min(570,number(screen,"width")-24);int group=page/4;
  for(int i=0;i<4;i++){int target=group*4+i;if(target>=names.length)break;button(screen,names[target],left+i*width/4,24,width/4-4,()->c(screen,"page",target));}
  button(screen,"< Pagina",left,48,90,()->c(screen,"page",Math.floorMod(page-1,names.length)));
  int next=(selected.getOrDefault(screen,-1)+1)%5;button(screen,"Preparar: "+ApocalypseSettings.PROFILES[next],left+94,48,width-188,()->prepare(screen));
  button(screen,"Pagina >",left+width-90,48,90,()->c(screen,"page",(page+1)%names.length));return new String[0];
 }
 @SuppressWarnings("unchecked")static void prepare(Object screen){try{c(screen,"remember");int n=(selected.getOrDefault(screen,-1)+1)%5;selected.put(screen,n);ApocalypseSettings.preset((Map<String,Double>)ZoneReflection.get(screen,"draft"),n);c(screen,"rebuildWidgets");set(screen,"status",ApocalypseSettings.PROFILES[n]+" preparado. Puedes editarlo; pulsa Aplicar para guardarlo.");}catch(RuntimeException e){set(screen,"status","Corrige el valor antes de preparar un perfil: "+e.getMessage());}}
 public static double scroll(String key,double value){return key.equals("profesion_loot_cantidad")?Math.max(0,Math.min(10,value)):CombatPanel.scroll(key,value);}
 public static String buttonText(String original,Object screen){return number(screen,"page")>=FIRST?"Ver probabilidades":original;}
 @SuppressWarnings("unchecked") public static boolean preset(Object screen){if(number(screen,"page")<FIRST)return CombatPanel.preset(screen);try{c(screen,"remember");Map<String,Double>d=(Map<String,Double>)ZoneReflection.get(screen,"draft");int page=number(screen,"page");if(page==10){set(screen,"status","Perfiles arriba; cura por nivel opcional. Cambia valores y pulsa Aplicar.");return true;}String[]ids=page==11?ApocalypseSettings.MUTANTS:ProfessionCatalog.IDS;String prefix=page==11?"mutante_pool_":"cadaver_pool_";double sum=Arrays.stream(ApocalypseSettings.weights(d,prefix,ids)).sum();c(screen,"rebuildWidgets");set(screen,"status",sum<=0?"Pool desactivado: todos los pesos son 0.":"Probabilidades actualizadas. Pasa el raton por cada casilla para ver su porcentaje.");}catch(RuntimeException e){set(screen,"status","Corrige los valores para ver probabilidades.");}return true;}
}
